from typing import List, Union
from time import sleep, time

from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug, log_warning
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UnexpectedState, UsageError


class ComponentCollection:
    """
    Represents collection of BTS components, i.e. collection of RMODs.
    Replaces Python list by covering basic list operations and enhancing them with BTS-specific operations.
    """
    def __init__(self, components: List[BtsComponent] = None):
        self._components = components if components is not None else []

    def __iter__(self):
        return iter(self._components)

    def __len__(self):
        return len(self._components)

    def __contains__(self, component):
        return component in self._components

    def __getitem__(self, index):
        return self._components[index]

    def __eq__(self, collection):
        return self._components == collection

    def append(self, component: BtsComponent):
        """
        Adds component to this collection.
        :param component: component which will be added
        """
        self._components.append(component)

    def extend(self, collection: Union[List, 'ComponentCollection']):
        """
        Adds all components from other collection to this collection.
        :param collection: other collection from which all components will be added
        """
        self._components.extend(collection)

    def clear(self):
        """ Removes all components from this collection. """
        self._components.clear()

    @pretty_log
    def find_by_name(self, name: str, raise_exc: bool = False) -> Union[BtsComponent, None]:
        """
        Finds and returns component with given name from this collection.
        :param name: component name which will be searched
        :param raise_exc: determines whether exception should be raised (True) or not (False) when component with given name is not found;
                          if turned off (False) then None will be returned instead;
                          defaults to False (exception will be not be raised)
        :return: component with given name or None if component with given name cannot be found and raise_exc is set to False
        :raises UsageError: if component with given name cannot be found and raise_exc is set to True
        """
        matches = self._find_by_name(name, raise_exc)
        return matches[0] if matches else None

    @pretty_log
    def check_if_name_exists(self, name: str):
        """
        Checks whether component name exist in this collection.
        :param name: component name which will be checked
        :raises UsageError: if component name cannot be found in this collection
        """
        log_info(f'Checking if component name {name} exist on BTS', to_console=True)
        self._find_by_name(name, raise_exc=True)

    @pretty_log
    def check_if_names_exist(self, names: List[str]):
        """
        Checks whether all components names exist in this collection.
        :param names: components names which will be checked
        :raises UsageError: if any component name cannot be found in this collection.
        """
        log_info(f'Checking if components names {names} exist on BTS', to_console=True)

        if not names:
            log_warning('No components names provided for existence check on BTS, this might indicate user error while defining them',
                        to_console=True)

        non_existing_components_names = [name for name in names if name not in [component.name for component in self._components]]

        if non_existing_components_names:
            raise UsageError(f'Components names which do not exist on BTS have been used: {non_existing_components_names}')

    @pretty_log
    def are_all_in_state(self, state: str = None, timeout: int = 0, interval: int = 1, **statuses: str) -> bool:
        """
        Informs whether all BTS components can reach given state.
        Either entire state or individual statuses need to be provided. Cannot provide both at the same time.
        :param state: name of expected, predefined state which then will be translated into collection of
                      individual statuses and their expected values used during state verification;
                      i.e. state='blocked';
                      defaults to None (state will not be used but statuses need to be provided)
        :param timeout: time (in seconds) in which expected state should be reached on all BTS components;
                        defaults to 0 (BTS components should be in expected state now)
        :param interval: time (in seconds) between consecutive states checks;
                         will be used only if timeout is greater than 0;
                         defaults to 1 (states will be checked every second)
        :param statuses: keyword arguments representing custom statuses and their expected values which should be used
                         during state verification;
                         i.e. procedural_status='configured';
                         if statuses are not provided then state needs to be provided
        :return: True if all statuses of all BTS components can reach their expected values, False otherwise
        :raises UnsupportedState: if both state and statuses are provided at the same time or
                                  neither of them is provided
        """
        return self._are_all_in_state(state, timeout, interval, **statuses)

    @pretty_log
    def check_state_on_all(self, state: str = None, timeout: int = 0, interval: int = 1, **statuses: str):
        """
        Checks whether all BTS components can reach given state.
        Either entire state or individual statuses need to be provided. Cannot provide both at the same time.
        :param state: name of expected, predefined state which then will be translated into collection of
                      individual statuses and their expected values used during state verification;
                      i.e. state='blocked';
                      defaults to None (state will not be used but statuses need to be provided)
        :param timeout: time (in seconds) in which expected state should be reached on all BTS components;
                        defaults to 0 (BTS components should be in expected state now)
        :param interval: time (in seconds) between consecutive states checks;
                         will be used only if timeout is greater than 0;
                         defaults to 1 (states will be checked every second)
        :param statuses: keyword arguments representing custom statuses and their expected values which should be used
                         during state verification;
                         i.e. procedural_status='configured';
                         if statuses are not provided then state needs to be provided
        :raises UnexpectedState: if given state cannot be reached on all BTS components
        :raises UnsupportedState: if both state and statuses are provided at the same time or
                                  neither of them is provided
        """
        state_as_expected = self._are_all_in_state(state, timeout, interval, **statuses)

        if not state_as_expected:
            raise UnexpectedState(f'State of {self._get_component_names()} is not as expected')

    @pretty_log
    def check_any_not_in_state(self, state: str = None, timeout: int = 0, interval: int = 1, **statuses: str):
        """
        Checks whether any BTS component can reach any state other than given one.
        Either entire state or individual statuses need to be provided. Cannot provide both at the same time.
        :param state: name of predefined state which then will be translated into collection of
                      individual statuses and their values used during state verification;
                      i.e. state='blocked';
                      defaults to None (state will not be used but statuses need to be provided)
        :param timeout: time (in seconds) in which any state other than given one should be reached;
                        defaults to 0 (any BTS component should not be in given state now)
        :param interval: time (in seconds) between consecutive states checks;
                         will be used only if timeout is greater than 0;
                         defaults to 1 (states will be checked every second)
        :param statuses: keyword arguments representing custom statuses and their values which should be used
                         during state verification;
                         it will be checked whether ALL statuses can reach values other than provided;
                         i.e. procedural_status='configured';
                         if statuses are not provided then state needs to be provided
        :raises UnexpectedState: if state other than given one cannot be reached on any BTS component
        :raises UnsupportedState: if both state and statuses are provided at the same time or
                                  neither of them is provided
        """
        state_as_expected = self._is_any_not_in_state(state, timeout, interval, **statuses)

        if not state_as_expected:
            raise UnexpectedState(f'State of {self._get_component_names()} is not as expected')

    def _find_by_name(self, name: str, raise_exc: bool) -> List[BtsComponent]:
        matches = list(filter(lambda component: component.name == name, self._components))

        if not matches and raise_exc:
            raise UsageError(f'Component name which does not exist on BTS has been used: {name}')

        return matches

    def _are_all_in_state(self, state: str = None, timeout: int = 0, interval: int = 1, **statuses: str) -> bool:
        self._log_details_of_expected_state(timeout, interval, state=state, **statuses)
        component_names = self._get_component_names()
        start_time = time()

        while True:
            if all([component.is_in_state(state=state, timeout=0, silent=True, **statuses)
                    for component in self._components]):
                log_debug(f'State of {component_names} is as expected')
                return True

            if time() - start_time >= timeout:
                log_debug(f'State of {component_names} is not as expected')
                return False

            sleep(interval)

    def _is_any_not_in_state(self, state: str = None, timeout: int = 0, interval: int = 1, **statuses: str) -> bool:
        self._log_details_of_not_expected_state(timeout, interval, state=state, **statuses)
        component_names = self._get_component_names()
        start_time = time()

        while True:
            if any([component.is_not_in_state(state=state, timeout=0, silent=True, **statuses)
                    for component in self._components]):
                log_debug(f'State of {component_names} is as expected')
                return True

            if time() - start_time >= timeout:
                log_debug(f'State of {component_names} is not as expected')
                return False

            sleep(interval)

    def _get_component_names(self):
        return ", ".join([component.name for component in self._components])

    def _log_details_of_expected_state(self, timeout, interval, **expected_state):
        component_names = self._get_component_names()
        timeout_msg = f" before {timeout}s timeout, every {interval}s" if timeout else ""
        log_info(f'Checking if state of {component_names} is as expected{timeout_msg}', to_console=True)
        log_debug(f'{component_names} expected state: \n{expected_state}')

    def _log_details_of_not_expected_state(self, timeout, interval, **not_expected_state):
        component_names = self._get_component_names()
        timeout_msg = f" before {timeout}s timeout, every {interval}s" if timeout else ""
        log_info(f'Checking if state of {component_names} is as expected{timeout_msg}', to_console=True)
        log_debug(f'{component_names} expected state: not \n{not_expected_state}')
